-- Small idempotent upgrade for databases with the existing queue already installed.
alter table zone_royale_private.matches drop constraint if exists matches_protocol_check;alter table zone_royale_private.matches add constraint matches_protocol_check check(protocol in(2,3,4));do $$ declare body text;begin body:=pg_get_functiondef('zone_royale_private.command(text,jsonb)'::regprocedure);if strpos(body,'protocol:=case when args->>''protocol''=''3'' then 3 else 2 end;')>0 then body:=replace(body,'protocol:=case when args->>''protocol''=''3'' then 3 else 2 end;','protocol:=case when args->>''protocol'' in (''3'',''4'') then (args->>''protocol'')::integer else 2 end;');execute body;elsif strpos(body,'in (''3'',''4'')')=0 then raise exception 'Queue protocol definition changed';end if;end $$;
